import{_ as e}from"./chunks/report.8JoF_Gem.js";import{_ as r,o as d,c as a,a2 as i}from"./chunks/framework.DbZkMlmv.js";const b=JSON.parse('{"title":"Comprendre les résultats","description":"","frontmatter":{},"headers":[],"relativePath":"guide/results.md","filePath":"guide/results.md"}'),o={name:"guide/results.md"};function s(n,t,l,c,u,p){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="comprendre-les-resultats" tabindex="-1">Comprendre les résultats <a class="header-anchor" href="#comprendre-les-resultats" aria-label="Permalink to &quot;Comprendre les résultats&quot;">​</a></h1><h2 id="score-de-risque-global" tabindex="-1">Score de risque global <a class="header-anchor" href="#score-de-risque-global" aria-label="Permalink to &quot;Score de risque global&quot;">​</a></h2><p>Chaque scan produit un <strong>score de risque de 0 à 100</strong>, calculé en pondérant les findings par sévérité :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Poids</th><th>Signification</th></tr></thead><tbody><tr><td>🔴 CRITICAL</td><td>×10</td><td>Vulnérabilité exploitable immédiatement</td></tr><tr><td>🟠 HIGH</td><td>×5</td><td>Risque élevé, correction urgente</td></tr><tr><td>🟡 MEDIUM</td><td>×2</td><td>Risque modéré, à corriger prochainement</td></tr><tr><td>🔵 LOW</td><td>×1</td><td>Risque faible, bonne pratique</td></tr><tr><td>ℹ️ INFO</td><td>×0</td><td>Information, pas de risque direct</td></tr></tbody></table><p>Le niveau global est ensuite déterminé ainsi :</p><table tabindex="0"><thead><tr><th>Score</th><th>Niveau</th></tr></thead><tbody><tr><td>0</td><td>✅ SAFE</td></tr><tr><td>1 - 30</td><td>🔵 LOW</td></tr><tr><td>31 - 60</td><td>🟡 MEDIUM</td></tr><tr><td>61 - 85</td><td>🟠 HIGH</td></tr><tr><td>86 - 100</td><td>🔴 CRITICAL</td></tr></tbody></table><p><img src="'+e+'" alt="Rapport de scan"></p><h2 id="structure-du-rapport" tabindex="-1">Structure du rapport <a class="header-anchor" href="#structure-du-rapport" aria-label="Permalink to &quot;Structure du rapport&quot;">​</a></h2><p>Le rapport est organisé en <strong>onglets par scanner</strong>. Chaque onglet affiche :</p><ul><li>Le nombre de findings par sévérité</li><li>Le détail de chaque finding : fichier concerné, ligne, description, recommandation</li></ul><h2 id="verification-des-versions-npm" tabindex="-1">Vérification des versions NPM <a class="header-anchor" href="#verification-des-versions-npm" aria-label="Permalink to &quot;Vérification des versions NPM&quot;">​</a></h2><p>L&#39;onglet <strong>NPM</strong> compare les dépendances avec la dernière version publiée sur npm. La version de référence est prioritairement celle du lockfile lorsqu&#39;il est présent.</p><table tabindex="0"><thead><tr><th>Écart</th><th>Sévérité</th><th>Code</th></tr></thead><tbody><tr><td>Majeur (<code>x</code> → <code>y</code>)</td><td>🔴 HIGH</td><td><code>NPM_OUTDATED</code></td></tr><tr><td>Mineur (<code>x.y</code> → <code>x.z</code>)</td><td>🟡 MEDIUM</td><td><code>NPM_OUTDATED</code></td></tr><tr><td>Correctif (<code>x.y.z</code> → <code>x.y.w</code>)</td><td>🔵 LOW</td><td><code>NPM_OUTDATED</code></td></tr></tbody></table><p>Le tableau des mises à jour indique la version courante, la dernière version disponible et la source de la version utilisée pour la comparaison.</p><h2 id="ui5-version" tabindex="-1">ui5 Version <a class="header-anchor" href="#ui5-version" aria-label="Permalink to &quot;ui5 Version&quot;">​</a></h2><p>Affiche de detail de la version ui5 x.x.x avec les données issue de <a href="https://ui5.sap.com/" target="_blank" rel="noreferrer">https://ui5.sap.com/</a> :</p><ul><li>Librairies,</li><li>Composants,</li><li>Themes.</li></ul>',17)])])}const f=r(o,[["render",s]]);export{b as __pageData,f as default};
